using System.Numerics;
namespace ToneCustoms.ShellStudio.Core;
public sealed class StarterTemplates { readonly GeometryService g=new(); public ShellProject Create(string type,string name){var p=new ShellProject{Name=name};if(type.Equals("Empty",StringComparison.OrdinalIgnoreCase))return p;var size=type.ToLowerInvariant() switch{"bedroom"=>new Vector2(4,4),"apartment"=>new Vector2(10,8),"house"=>new Vector2(14,12),"store"=>new Vector2(12,8),"office"=>new Vector2(14,10),"warehouse"=>new Vector2(24,18),"restaurant"=>new Vector2(16,12),"club"=>new Vector2(18,14),_=>new Vector2(8,8)};p.Objects.Add(g.Floor(Vector3.Zero,size.X,size.Y));p.Objects.Add(g.Ceiling(new(0,0,3),size.X,size.Y));p.Objects.Add(g.Wall(new(0,-size.Y/2,1.5f),size.X));p.Objects.Add(g.Wall(new(0,size.Y/2,1.5f),size.X));return p;} }
